<?php declare(strict_types=1);namespace App\Services;use App\Core\Config;final class AiService{public function __construct(private Config $config){}public function analyze(string $tool,string $content):array{$words=str_word_count(strip_tags($content));$sentences=max(1,preg_match_all('/[.!?]+/',$content));$score=max(1,min(100,100-(int)($words/35)+($sentences>3?5:0)));$keywords=array_slice(array_keys(array_count_values(str_word_count(strtolower(strip_tags($content)),1))),0,12);return ['provider'=>'local-quality-engine','tool'=>$tool,'score'=>$score,'summary'=>"Processed {$words} words across {$sentences} sentence groups for {$tool}.",'recommendations'=>['Improve topical depth with authoritative entities.','Use concise headings that match search intent.','Add internal links to relevant supporting pages.','Verify claims and add trust signals for EEAT.'],'keywords'=>$keywords];}}
